with j as (select * from jsonb_to_recordset($law7d0012$[{"code_id":"APK_RF","article_number":"242","version_date":"2002-07-24","article_text":"В заявлении должны быть указаны:\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименование и место нахождения иностранного суда либо наименование и состав третейского суда или международного коммерческого арбитража, место его нахождения;\n\n3) наименование взыскателя, его место нахождения или место жительства;\n\n4) наименование должника, его место нахождения или место жительства;\n\n5) сведения о решении иностранного суда или об иностранном арбитражном решении, о признании и приведении в исполнение которых ходатайствует взыскатель;\n\n6) ходатайство взыскателя о признании и приведении в исполнение решения иностранного суда или иностранного арбитражного решения;\n\n7) перечень прилагаемых документов.\n\nВ заявлении о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения могут быть также указаны номера телефонов, факсов, адреса электронной почты взыскателя, должника, их представителей и иные сведения.\n\n1) удостоверенная надлежащим образом копия решения иностранного суда или иностранного арбитражного решения, о признании и приведении в исполнение которых ходатайствует взыскатель;\n\n2) документ, удостоверенный надлежащим образом и подтверждающий вступление решения иностранного суда в законную силу, если это не указано в тексте самого решения;\n\n3) документ, удостоверенный надлежащим образом и подтверждающий, что должник был своевременно и в надлежащей форме извещен о разбирательстве дела в иностранном суде, о признании и приведении в исполнение решения которого ходатайствует взыскатель;\n\n4) доверенность или иной документ, удостоверенные надлежащим образом и подтверждающие полномочия лица, подписавшего заявление в арбитражный суд;\n\n5) документ, подтверждающий направление должнику копии заявления о признании и приведении в исполнение решения иностранного суда;\n\n6) заверенный надлежащим образом перевод указанных в пунктах 1 - 5 настоящей части документов на русский язык.\n\n1) надлежащим образом заверенное подлинное иностранное арбитражное решение или его надлежащим образом заверенная копия;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия;\n\n3) надлежащим образом заверенный перевод на русский язык документов, указанных в пунктах 1 и 2 настоящей части.","article_title":"Статья 242. Заявление о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"adecce77c95d08acb69b1b9d4a45d76d573b399569ec8decf34e3eb7f2967e4f"},{"code_id":"APK_RF","article_number":"243","version_date":"2002-07-24","article_text":"1. Заявление о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения рассматривается судьей единолично по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с учетом особенностей, установленных настоящей главой, в срок, не превышающий одного месяца со дня его поступления в арбитражный суд субъекта Российской Федерации.\n\n2. Арбитражный суд извещает лиц, участвующих в деле, о времени и месте судебного заседания. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела.\n\n3. При рассмотрении дела арбитражный суд в судебном заседании устанавливает наличие или отсутствие оснований для признания и приведения в исполнение решения иностранного суда и иностранного арбитражного решения, предусмотренных статьей 244 настоящего Кодекса, путем исследования представленных в арбитражный суд доказательств, обоснования заявленных требований и возражений, а также разъяснений иностранного суда или третейского суда, принявших решение, если арбитражный суд истребует такие разъяснения.\n\n4. При рассмотрении дела арбитражный суд не вправе пересматривать решение иностранного суда по существу.\n\n5. Если в иностранном суде находится на рассмотрении заявление об отмене или о приостановлении исполнения решения иностранного суда и иностранного арбитражного решения, арбитражный суд, в котором рассматривается заявление о признании и приведении в исполнение этого решения, может по ходатайству одной из сторон отложить рассмотрение заявления о выдаче исполнительного листа.\n\n6. В случае, указанном в части 5 настоящей статьи, арбитражный суд, в котором рассматривается заявление о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения, по ходатайству стороны, обратившейся с таким заявлением, может обязать другую сторону предоставить надлежащее обеспечение по правилам, предусмотренным настоящим Кодексом.\n\n7. Если в случае, указанном в части 5 настоящей статьи, рассмотрение заявления о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения было отложено арбитражным судом, после разрешения иностранным судом заявления об отмене или о приостановлении исполнения решения иностранного суда и иностранного арбитражного решения арбитражный суд, в котором рассматривается заявление о признании и приведении в исполнение этого решения, рассматривает заявление о признании и приведении в исполнение этого решения с учетом вынесенного иностранным судом судебного акта в соответствии с международными договорами Российской Федерации и федеральными законами.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 243. Порядок рассмотрения заявления о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7f594a489b6ad033b8a44a94781bde76c1f744a1b933997285dccdc807a8ece6"},{"code_id":"APK_RF","article_number":"244","version_date":"2002-07-24","article_text":"1. Арбитражный суд отказывает в признании и приведении в исполнение решения иностранного суда полностью или в части в случае, если:\n\n1) решение по закону государства, на территории которого оно принято, не вступило в законную силу;\n\n2) сторона, против которой принято решение, не была своевременно и надлежащим образом извещена о времени и месте рассмотрения дела или по другим причинам не могла представить в суд свои объяснения;\n\n3) рассмотрение дела в соответствии с международным договором Российской Федерации или федеральным законом относится к исключительной компетенции суда в Российской Федерации, за исключением случаев, указанных в части 5 статьи 2481 настоящего Кодекса; (В редакции Федерального закона от 08.06.2020 № 171-ФЗ)\n\n4) имеется вступившее в законную силу решение суда в Российской Федерации, принятое по спору между теми же лицами, о том же предмете и по тем же основаниям;\n\n5) на рассмотрении суда в Российской Федерации находится дело по спору между теми же лицами, о том же предмете и по тем же основаниям, производство по которому возбуждено до возбуждения производства по делу в иностранном суде, или суд в Российской Федерации первым принял к своему производству заявление по спору между теми же лицами, о том же предмете и по тем же основаниям;\n\n6) истек срок давности приведения решения иностранного суда к принудительному исполнению и этот срок не восстановлен арбитражным судом;\n\n7) исполнение решения иностранного суда противоречило бы публичному порядку Российской Федерации.","article_title":"Статья 244. Основания отказа в признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"974e5ae2e41dd57ee7a7c05aff99eb114705f4da4cae358f3b9ad90e10341615"},{"code_id":"APK_RF","article_number":"245","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения арбитражный суд выносит определение по правилам, установленным в главе 20 настоящего Кодекса для принятия решения.\n\n2. В определении по делу о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения должны содержаться:\n\n1) наименование и место нахождения иностранного суда либо наименование и состав третейского суда или международного коммерческого арбитража, принявших решение;\n\n2) наименования взыскателя и должника;\n\n3) сведения о решении иностранного суда или об иностранном арбитражном решении, о признании и приведении в исполнение которого ходатайствовал взыскатель;\n\n4) указание на признание и приведение в исполнение решения иностранного суда или иностранного арбитражного решения либо на отказ в признании и приведении в исполнение решения иностранного суда или иностранного арбитражного решения.","article_title":"Статья 245. Определение арбитражного суда по делу о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9ae0c8bc65b0bffee41412dcb9e7b2e4c53aa94cba47bd8c84cd823ddb694394"},{"code_id":"APK_RF","article_number":"245.1","version_date":"2002-07-24","article_text":"1. Решения иностранных судов и иностранные арбитражные решения, не требующие принудительного исполнения, признаются в Российской Федерации, если их признание предусмотрено международным договором Российской Федерации и федеральным законом.\n\n2. Решения иностранных судов и иностранные арбитражные решения, не требующие принудительного исполнения, признаются в Российской Федерации без какого-либо дальнейшего производства, если со стороны заинтересованного лица не поступят возражения относительно этого.\n\n3. Заинтересованное лицо в течение одного месяца после того, как ему стало известно о решении иностранного суда или об иностранном арбитражном решении, может заявить возражения относительно признания этого решения в арбитражный суд субъекта Российской Федерации по месту нахождения или месту жительства заинтересованного лица либо месту нахождения его имущества, а если заинтересованное лицо не имеет места жительства, места нахождения или имущества в Российской Федерации, в Арбитражный суд города Москвы.\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименование и место нахождения иностранного суда либо состав третейского суда или международного коммерческого арбитража, его место нахождения;\n\n3) наименование заинтересованного лица, его место нахождения или место жительства;\n\n4) сведения о решении иностранного суда или об иностранном арбитражном решении, возражения против признания которых заявляет заинтересованное лицо;\n\n5) ходатайство заинтересованного лица об отказе в признании решения иностранного суда или иностранного арбитражного решения с приведением оснований для отказа в таком признании, а также с обоснованием нарушения указанным решением прав и законных интересов заинтересованного лица в сфере предпринимательской и иной экономической деятельности в Российской Федерации;\n\n6) перечень прилагаемых документов.\n\n1) удостоверенная надлежащим образом копия решения иностранного суда или иностранного арбитражного решения, возражения против признания которых заявляет заинтересованное лицо;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия, если заинтересованным лицом заявляются возражения против признания иностранного арбитражного решения;\n\n3) доверенность или иной документ, удостоверенные надлежащим образом и подтверждающие полномочия лица, подписавшего заявление в арбитражный суд;\n\n4) документ об уплате государственной пошлины за подачу заявления в размере, предусмотренном федеральным законом для оплаты искового заявления неимущественного характера;\n\n5) заверенный надлежащим образом перевод на русский язык документов, указанных в пунктах 1 - 3 настоящей части.\n\n(Дополнение статьей - Федеральный закон от 29.12.2015 № 409-ФЗ)","article_title":"Статья 245.1. Решения иностранных судов и иностранные арбитражные решения, не требующие принудительного исполнения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e0d440a65ed6970189f383284fce86cc65d166f0026e43a2388034a9c71102a"},{"code_id":"APK_RF","article_number":"246","version_date":"2002-07-24","article_text":"1. Принудительное исполнение решения иностранного суда или иностранного арбитражного решения производится на основании исполнительного листа, выдаваемого арбитражным судом, вынесшим определение о признании и приведении в исполнение решения иностранного суда или иностранного арбитражного решения, в порядке, предусмотренном настоящим Кодексом и федеральным законом об исполнительном производстве.\n\n2. Решение иностранного суда или иностранное арбитражное решение может быть предъявлено к принудительному исполнению в срок, не превышающий трех лет со дня вступления его в законную силу. В случае пропуска указанного срока он может быть восстановлен арбитражным судом по ходатайству взыскателя по правилам, предусмотренным главой 10 настоящего Кодекса.\n\nРАЗДЕЛ V. ПРОИЗВОДСТВО ПО ДЕЛАМ С УЧАСТИЕМ ИНОСТРАННЫХ ЛИЦ","article_title":"Статья 246. Принудительное исполнение решения иностранного суда или иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fd1cd33d2887283fbe8a3d9a42bc43f22b4612e7147b191262766073bf5db107"},{"code_id":"APK_RF","article_number":"247","version_date":"2002-07-24","article_text":"1. Арбитражные суды в Российской Федерации рассматривают дела по экономическим спорам и другие дела, связанные с осуществлением предпринимательской и иной экономической деятельности, с участием иностранных организаций, международных организаций, иностранных граждан, лиц без гражданства, осуществляющих предпринимательскую и иную экономическую деятельность (далее - иностранные лица), в случае, если:\n\n1) ответчик находится или проживает на территории Российской Федерации либо на территории Российской Федерации находится имущество ответчика;\n\n2) орган управления, филиал или представительство иностранного лица находится на территории Российской Федерации;\n\n3) спор возник из договора, по которому исполнение должно иметь место или имело место на территории Российской Федерации;\n\n4) требование возникло из причинения вреда имуществу действием или иным обстоятельством, имевшими место на территории Российской Федерации или при наступлении вреда на территории Российской Федерации;\n\n5) спор возник из неосновательного обогащения, имевшего место на территории Российской Федерации;\n\n6) истец по делу о защите деловой репутации находится в Российской Федерации;\n\n7) спор возник из отношений, связанных с обращением ценных бумаг, выпуск которых имел место на территории Российской Федерации;\n\n8) заявитель по делу об установлении факта, имеющего юридическое значение, указывает на наличие этого факта на территории Российской Федерации;\n\n9) спор возник из отношений, связанных с государственной регистрацией имен и других объектов и оказанием услуг в международной ассоциации информационно-телекоммуникационных сетей \"Интернет\" на территории Российской Федерации; (В редакции Федерального закона от 11.07.2011 № 200-ФЗ)\n\n10) в других случаях при наличии тесной связи спорного правоотношения с территорией Российской Федерации.","article_title":"Статья 247. Компетенция арбитражных судов в Российской Федерации по делам с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5df1a1ca11f2f9576ed3bd740e822b2b5f4db955e45c02b945d4b43926aba049"},{"code_id":"APK_RF","article_number":"248","version_date":"2002-07-24","article_text":"1. К исключительной компетенции арбитражных судов в Российской Федерации по делам с участием иностранных лиц относятся дела:\n\n1) по спорам в отношении находящегося в государственной собственности Российской Федерации имущества, в том числе по спорам, связанным с приватизацией государственного имущества и принудительным отчуждением имущества для государственных нужд;\n\n2) по спорам, предметом которых являются недвижимое имущество, если такое имущество находится на территории Российской Федерации, или права на него;\n\n3) по спорам, связанным с регистрацией или выдачей патентов, регистрацией и выдачей свидетельств на товарные знаки, промышленные образцы, полезные модели или регистрацией других прав на результаты интеллектуальной деятельности, которые требуют регистрации или выдачи патента либо свидетельства в Российской Федерации;\n\n4) по спорам о признании недействительными записей в государственные реестры (регистры, кадастры), произведенных компетентным органом Российской Федерации, ведущим такой реестр (регистр, кадастр);\n\n5) по спорам, связанным с учреждением, ликвидацией или регистрацией на территории Российской Федерации юридических лиц и индивидуальных предпринимателей, а также с оспариванием решений органов этих юридических лиц.\n\n2. В исключительной компетенции арбитражных судов в Российской Федера\n\nции находятся также предусмотренные в разделе III настоящего Кодекса дела с участием иностранных лиц, возникающие из административных и иных публичных правоотношений.","article_title":"Статья 248. Исключительная компетенция арбитражных судов в Российской Федерации по делам с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e4b4e4a746f28603987ea851b550ff1766a3361b1b6f22afcfd2332b91e7a2a"},{"code_id":"APK_RF","article_number":"248.1","version_date":"2002-07-24","article_text":"1. Если иное не установлено международным договором Российской Федерации или соглашением сторон, в соответствии с которыми рассмотрение споров с их участием отнесено к компетенции иностранных судов, международных коммерческих арбитражей, находящихся за пределами территории Российской Федерации, к исключительной компетенции арбитражных судов в Российской Федерации относятся дела:\n\n1) по спорам с участием лиц, в отношении которых применяются меры ограничительного характера иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза;\n\n2) по спорам одного российского или иностранного лица с другим российским или иностранным лицом, если основанием для таких споров являются ограничительные меры, введенные иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза в отношении граждан Российской Федерации и российских юридических лиц.\n\n2. В целях настоящей главы к лицам, в отношении которых иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза применяются меры ограничительного характера, относятся:\n\n1) граждане Российской Федерации, российские юридические лица, в отношении которых иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза применяются меры ограничительного характера;\n\n2) иностранные юридические лица, в отношении которых иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза применяются меры ограничительного характера и основанием для применения таких мер являются ограничительные меры, введенные иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза в отношении граждан Российской Федерации и российских юридических лиц.\n\n3. Лица, указанные в части 2 настоящей статьи, вправе:\n\n1) обратиться за разрешением спора в арбитражный суд субъекта Российской Федерации по месту своего нахождения или месту жительства при условии, что в производстве иностранного суда или международного коммерческого арбитража, находящихся за пределами территории Российской Федерации, отсутствует спор между теми же лицами, о том же предмете и по тем же основаниям;\n\n2) обратиться в порядке, предусмотренном статьей 2482 настоящего Кодекса, с заявлением о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации.\n\n4. Положения настоящей статьи применяются также в случае, если соглашение сторон, в соответствии с которым рассмотрение споров с их участием отнесено к компетенции иностранного суда и международного коммерческого арбитража, находящихся за пределами территории Российской Федерации, неисполнимо по причине применения в отношении одного из лиц, участвующих в споре, мер ограничительного характера иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза, создающих такому лицу препятствия в доступе к правосудию.\n\n5. Положения настоящей статьи не препятствуют признанию и приведению в исполнение решения иностранного суда или иностранного арбитражного решения, принятых по иску лица, указанного в части 2 настоящей статьи, либо если это лицо не возражало против рассмотрения с его участием спора иностранным судом, международным коммерческим арбитражем, находящимися за пределами территории Российской Федерации, в том числе не обращалось с заявлением о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 08.06.2020 № 171-ФЗ)","article_title":"Статья 248.1. Исключительная компетенция арбитражных судов в Российской Федерации по спорам с участием лиц, в отношении которых введены меры ограничительного характера","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"89619448462f5685ffa7c892e03e6cd95ede6e9015a3ac1c4b1aed8b842858a3"},{"code_id":"APK_RF","article_number":"248.2","version_date":"2002-07-24","article_text":"1. Лицо, в отношении которого инициировано разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, по спорам, указанным в статье 2481 настоящего Кодекса, или при наличии доказательств того, что такое разбирательство будет инициировано, вправе обратиться в арбитражный суд субъекта Российской Федерации по месту своего нахождения или месту жительства с заявлением о запрете инициировать или продолжать такое разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, в порядке, установленном настоящей статьей.\n\n2. В заявлении, предусмотренном частью 1 настоящей статьи, должны быть указаны:\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименование заявителя, его адрес или место жительства, а также наименование лица, в отношении которого требуется установить запрет, его адрес или место жительства;\n\n3) сведения о требованиях, которые могут быть предъявлены или уже предъявлены в иностранном суде, международном коммерческом арбитраже;\n\n4) обстоятельства, подтверждающие исключительную компетенцию арбитражных судов в Российской Федерации по рассмотрению спора, в том числе обстоятельства (при их наличии), подтверждающие, что соглашение сторон, в соответствии с которым рассмотрение спора с их участием отнесено к компетенции иностранного суда, международного коммерческого арбитража, находящихся за пределами территории Российской Федерации, не может быть исполнено стороной спора;\n\n5) требование заявителя о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации;\n\n6) перечень прилагаемых документов.\n\n3. В заявлении, предусмотренном частью 1 настоящей статьи, могут быть также указаны номера телефонов, факсов, адреса электронной почты заявителя и лиц, которые могут инициировать или инициировали разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, а также их представителей.\n\n4. К заявлению, предусмотренному частью 1 настоящей статьи, прилагаются:\n\n1) копии документов, подтверждающих намерение инициировать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, либо факт начала разбирательства в иностранном суде, международном коммерческом арбитраже, в том числе претензии, требования, иски и иные документы;\n\n2) копии документов, подтверждающих исключительную компетенцию арбитражных судов в Российской Федерации по рассмотрению спора;\n\n3) иные документы, указанные в статье 126 настоящего Кодекса.\n\n5. Заявление, предусмотренное частью 1 настоящей статьи, рассматривается судьей единолично по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с учетом особенностей, установленных настоящей статьей.\n\n6. Арбитражный суд извещает лиц, участвующих в деле, о времени и месте судебного заседания в порядке, установленном настоящим Кодексом. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения заявления, предусмотренного частью 1 настоящей статьи.\n\n7. По результатам рассмотрения заявления, предусмотренного частью 1 настоящей статьи, арбитражный суд выносит определение по правилам, установленным главой 20 настоящего Кодекса для вынесения решений.\n\n8. В определении о запрете или об отказе в запрете стороне инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, должны содержаться:\n\n1) наименования заявителя и лица, в отношении которого выносится запрет;\n\n2) сведения о требованиях, которые могут быть предъявлены в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, либо сведения о конкретном разбирательстве в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, в отношении которых устанавливается запрет;\n\n3) указание на удовлетворение заявления о запрете лицу инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, либо на отказ в удовлетворении такого заявления.\n\n9. Определение арбитражного суда по делу о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, по спорам, указанным в статье 2481 настоящего Кодекса, может быть обжаловано в кассационном порядке в арбитражный суд округа в течение одного месяца со дня вынесения определения.\n\n10. Арбитражный суд на основе принципов справедливости, соразмерности и недопустимости извлечения выгоды из незаконного или недобросовестного поведения по требованию заявителя вправе присудить в его пользу денежную сумму, подлежащую взысканию с лица, в отношении которого вынесен запрет инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, на случай неисполнения им судебного акта. Размер подлежащей взысканию арбитражным судом денежной суммы не должен превышать размера исковых требований, предъявленных в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, и понесенных стороной спора судебных расходов.\n\n(Дополнение статьей - Федеральный закон от 08.06.2020 № 171-ФЗ)","article_title":"Статья 248.2. Запрет инициировать или продолжать разбирательство по спорам с участием лиц, в отношении которых введены меры ограничительного характера","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"de43cb8183e021278fbda594cdc308bf387e7401391d5a81d03066903d401098"},{"code_id":"APK_RF","article_number":"249","version_date":"2002-07-24","article_text":"1. В случае, если стороны, хотя бы одна из которых является иностранным лицом, заключили соглашение, в котором определили, что арбитражный суд в Российской Федерации обладает компетенцией по рассмотрению возникшего или могущего возникнуть спора, связанного с осуществлением ими предпринимательской и иной экономической деятельности, арбитражный суд в Российской Федерации будет обладать исключительной компетенцией по рассмотрению данного спора при условии, что такое соглашение не изменяет исключительную компетенцию иностранного суда.\n\n2. Соглашение об определении компетенции должно быть заключено в письменной форме.","article_title":"Статья 249. Соглашение об определении компетенции арбитражных судов в Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"822279f33f68075e471e834a76a55f8d2348c6952a37761828c4b6000a0f195c"}]$law7d0012$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
